-- ==================== 0020_assistant_usage_limits.sql ====================

-- Counters only: never store chat text, raw IP addresses, or provider secrets.
create table private.assistant_usage (
 subject_hash text not null check(subject_hash ~ '^[0-9a-f]{64}$'),
 audience text not null check(audience in ('guest','member')),
 window_start timestamptz not null,
 questions int not null check(questions > 0),
 primary key(subject_hash,audience,window_start)
);
alter table private.assistant_usage enable row level security;
revoke all on private.assistant_usage from public,anon,authenticated;

-- Called only by the Edge Function after verifying any supplied user JWT.
create function public.assistant_access_quota(subject_hash text,member_id uuid default null,consume boolean default true)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_audience text; starts timestamptz; resets timestamptz; cap int; used int=0; claimed int; permitted boolean;
begin
 if subject_hash is null or subject_hash !~ '^[0-9a-f]{64}$' or consume is null then raise exception 'Invalid quota request'; end if;
 if member_id is not null then
  if not exists(select 1 from public.profiles where id=member_id and account_status='active') then raise exception 'Active account required'; end if;
  return jsonb_build_object('audience','member','limit',null,'remaining',null,'resets_at',null,'allowed',true);
 else
  v_audience='guest'; cap=10; starts=((now() at time zone 'Asia/Manila')::date)::timestamp at time zone 'Asia/Manila'; resets=starts+interval '1 day';
 end if;
 if consume then
  delete from private.assistant_usage where window_start<now()-interval '2 days';
  insert into private.assistant_usage as usage(subject_hash,audience,window_start,questions)
  values(subject_hash,v_audience,starts,1)
  on conflict on constraint assistant_usage_pkey do update set questions=usage.questions+1 where usage.questions<cap
  returning questions into claimed;
 end if;
 select u.questions into used from private.assistant_usage u where u.subject_hash=assistant_access_quota.subject_hash and u.audience=v_audience and u.window_start=starts;
 used=coalesce(used,0);
 permitted=case when consume then claimed is not null else used<cap end;
 return jsonb_build_object('audience',v_audience,'limit',cap,'remaining',greatest(cap-used,0),'resets_at',resets,'allowed',permitted);
end $$;
revoke execute on function public.assistant_access_quota(text,uuid,boolean) from public,anon,authenticated;
grant execute on function public.assistant_access_quota(text,uuid,boolean) to service_role;

